    def 경기신보검토안프롬프트(self):
        self.새창()
        self.문서여백(20, 20, 15, 15, 10, 10)
        self.폰트('맑은 고딕')
        self.글자크기(14)
        self.진하게()
        self.글자색(255, 0, 0)
        self.문장('※ 파란색 부분에 내용을 입력해 주세요. (이 줄은 삭제)\r\n')
        self.글자크기(10)
        self.글자색(0, 0, 0)
        self.문장('아래 <형식>에 맞춰 ')
        self.글자크기(14)
        self.글자색(0, 0, 255)
        self.문장('‘******** 검토안’')
        self.글자크기(10)
        self.글자색(0, 0, 0)
        self.문장('보고서 내용을 작성해 줘.\r\n\r\n')
        self.글자크기(8)
        self.글자색(0, 0, 0)
        self.기본글자()
        self.문장('[작성 기준] \r\n- 모든 문장은 반드시 보고서용 개조식 문구로 작성(모든 문장 종결은 명사형으로만 작성) \r\n→ 서술형 또는 조사형 종결, ‘~함’, ‘~임’, ‘~입니다’, ‘~입니다만’ 등 종결 어미는 완전히 배제 \r\n- 맨 앞의 “제목:”, “별”, “□”, “ㅇ”, “당구장” 형식 표기는 그대로 유지(글자 수 표기 금지) \r\n→ “당구장”을 “※”로 표기하는 등 형식 문구 임의 변경 금지 \r\n- “키워드”는 주요 내용을 함축하는 핵심어로 작성 \r\n- 주요 내용 중 ‘참고 내용, 출처, 주석 등’ 부연 설명이 필요할 경우 다음 줄에 “별 ” 또는 “당구장 ”추가 후 작성 \r\n→ 부연 설명이 불필요할 경우 “별” 또는 “당구장” 라인은 삭제(“별”과 “당구장”은 같은 문장에 동시 사용 금지) \r\n[글자 수 기준] \r\n- 글자 수는 띄어쓰기 공백, 한글, 숫자, 영문, 특수문자 등 모든 표시를 1블록당 1자로 계산 \r\n- 형식에 있는 각 항목별 “주요 내용” 문장은 반드시 ** ‘공백’ 포함 63~73자 **로 작성하여 출력 \r\n- 띄어쓰기의 ‘공백’과 “(키워드)”도 글자 수에 포함하여 계산 \r\n- “별” 또는 “당구장” 내용은 반드시 ** ‘공백’ 포함 40자 이내 **로 작성하여 출력 \r\n- 앞의 “□” 또는 “ㅇ”, “바”, “별”, “당구장”은 글자 수 계산에서 제외 \r\n[검토 기준] \r\n- 초안 작성 후 각 항목별 글자 수를 계산하여 기준에 맞게 문장 수정(글자 수 범위를 벗어나면 다시 수정) \r\n- 최종 출력 전 전체 내용의 일관성 및 보고서 문체 적정성 점검 \r\n[출력 기준] \r\n각 항목별 요구하는 글자 수가 [글자 수 기준]에 맞는지 검토 후 출력 \r\n- 답변은 설명 없이 최종 결과(형식)만 출력(형식 외 문구 일절 출력 금지) \r\n\r\n< 형식 > \r\n제목: [22자 이내] \r\n□ 개요 \r\nㅇ 주요 내용 [40~60자] \r\n\r\n□ 현황 및 문제점 \r\nㅇ (키워드) 주요 내용 [40~60자] \r\nㅇ (키워드) 주요 내용 [40~60자] \r\n별 또는 당구장 [40자 이내] \r\n\r\n□ 개선사항 \r\nㅇ (키워드) 주요 내용 [40~60자] \r\nㅇ (키워드) 주요 내용 [40~60자] \r\n별 또는 당구장 [40자 이내] \r\n\r\n□ 기대효과 \r\nㅇ (키워드) 주요 내용 [40~60자] \r\nㅇ (키워드) 주요 내용 [40~60자] \r\n별 또는 당구장 [40자 이내] ')

