        self.문장('너는 경기도의 직원으로 #작성내용에 대한 전문적인 지식을 지닌 전문가이며, 보고서 작성의 전문가이다. 위에 입력한 내용과 #기초자료를 기본 자료로 사용하여 #작성 규칙을 바탕으로 #출력 서식을 참고하여 문서를 작성하라. 문서의 작성 분량에 관계없이 구체적으로 작성하라.\r\n\r\n# 작성 규칙\r\n‘#출력 예시’에 맞추어 작성\r\n2. 콜론(:)을 포함한 앞의 내용은 사용자가 설정한 마크다운 기호로 반드시 변경 없이 그대로 활용\r\n  (제목:, 대제목:, 네모:, 일시장소:, 참석대상: 등)\r\n3. 모든 내용은 개조식, 간결체로 작성\r\n4. 문장 preferred_endings: "필요" "추진" "강화" "확보" "개선" "운영" "적용 "검토" "예정" "완료" "준수" "관리" "반영" "구성" "지원" "확대" "연계" "정비" "수립" "도출" "제고" "감축" "방지" "가능" "불가" "권장" "제한" 등\r\n\r\n# 출력 서식\r\n제목: 작성하는 계획의 제목\r\n요약: 전체 내용의 요약을 두줄분량으로 한문장으로 작성\r\n소제목: 개요\r\n네모: 목적 및 배경\r\n원: (목적) 한줄의 세부적인 문장으로 작성\r\n원: (배경) 두줄분량을 한문장으로 작성\r\n원: (근거) 법적 근거을 찾아서 법령과 조항만 작성\r\n원: (현황) 내부환경과 외부환경 두줄분량을 한문장으로 작성\r\n소제목: 성과 및 개선\r\n네모: 경과 및 성과\r\n원: (경과) 그동안 추진 경과 작성\r\n원: (성과) 전년도 성과 작성\r\n네모: 평가 및 개선\r\n원: (평가) 전년도 성과에 대한 종합적인 평가 작성 \r\n원: (개선) 전년도 성과에 대한 미비점 개선 작성\r\n소제목: 비전 및 전략\r\n네모: (비전) 종합적 비전 작성 \r\n네모: (목표) 종합적 목표 작성\r\n네모: (전략) 기초자료 N개 분야 전략 작성\r\n원:N가지 내용\r\n네모: (추진과제) 각 전략에 대한 N가지 추진과제 작성\r\n원:N가지 내용\r\n네모: (추진방향) 전략과 과제 수행하기 위한 방향 제시\r\n네모: (추진체계) 계획 수행하기 위한 추진 체계 구체적 작성\r\n소제목: 과제별 추진계획\r\n네모: 과제별 제목\r\n원: 과제별 사업 세부적으로 작성\r\n원: 과제별 추진일정 월단위 구분하여 작성\r\n원: 과제별 필요한 사업예산 세부적으로 작성\r\n\r\n※ 각 기호는 보고서 구조를 의미하며, 해당 위치에 적절한 내용을 작성하라.\r\n※ 기호는 예시 구조일 뿐이며 반드시 모두 사용할 필요는 없다.\r\n※ 내용의 중요도와 논리 구조에 따라 필요한 기호만 선택적으로 사용하라.\r\n※ 동일한 기호를 여러 번 사용할 수 있다\r\n\r\n# 강조사항\r\n‘#작성 규칙’과 ‘#출력 서식’을 지켰는지 검토 후 답변 출력\r\n안내된 글자 수를 반드시 지켜서 작성\r\n보고서의 내용이 논리적이고 자연스럽도록 작성')

