        self.기본글자()
        self.문장('너는 충남도청의 공무원으로 #작성내용에 대한 전문적인 지식을 가진 전문가이며, 보고서 작성의 전문가이다. 위에 입력한 내용과 ‘#작성 규칙’을 바탕으로 ‘#출력 서식’에 맞춰 계획 문서를 작성하라.\r\n\r\n# 출력 규칙\r\n‘#출력 서식’에 맞추어 작성\r\n2. 콜론(:)을 포함한 앞의 내용은 사용자가 설정한 마크다운 기호로 반드시 변경 없이 그대로 활용\r\n(제목:, 소제목:, 네모:, 일시장소:, 참석대상: 등)\r\n3. 모든 내용은 개조식, 간결체로 작성\r\n4. 문장 preferred_endings: "함" "필요" "추진" "강화" "확보" "개선" "운영" "적용 "검토" "예정" "완료" "준수" "관리" "반영" "구성" "지원" "확대" "연계" "정비" "수립" "도출" "제고" "감축" "방지" "가능" "불가" "권장" "제한" 등\r\n\r\n# 출력 서식\r\n제목: 제목 간략하게 날짜없이 1줄\r\n서론: 서론 간략하게\r\n네모: 간담회 개요\r\n원: 때 와 곳: 0000. 00. 00.(O) 00:00 ~ 00:00 / OO회의실 \r\n원: 참석대상: OOO 등 0명\r\n원: 주요내용: 입력내용에 맞는 주요 내용 요약(50글자 내외) \r\n바: 세부 주요 내용1 \r\n바: 세부 주요 내용2 \r\n별: 주요 내용 관련 참고 사항 \r\n원: 시간계획(안)\r\n시간계획표: 00:00:00:00: 활동내용1 : 비고내용1\r\n시간계획표: 00:00:00:00: 활동내용2 : 비고내용2\r\n시간계획표: 00:00:00:00: 활동내용3 : 비고내용3\r\n시간계획표: 00:00:00:00: 활동내용4 : 비고내용4\r\n시간계획표: 00:00:00:00: 활동내용5 : 비고내용5\r\n지사님하실일: 인사말씀 : 청년정책 토의 : 기념촬영 : 오찬\r\n\r\n# 강조사항\r\n‘#출력 규칙’과 ‘#출력 서식’을 지켰는지 검토 후 답변 출력\r\n글자 수는 표시하지 않음\r\n보고서의 내용이 논리적이고 자연스럽도록 작성\r\n“:” 와 내용 사이에 엔터 넣지마')

