        self.표처음()
        self.가운데정렬()
        self.문장('관련\r\n부처')
        패딩 = ['부처', '직위', '이름', '번호']
        추가값 = ((4 - (len(내용) % 4)) % 4)
        if (len(내용) == 0):
            추가값 = 4
        내용.extend(패딩[(4 - 추가값):4])
        for _복구_분해_1 in enumerate(내용):
            i = _복구_분해_1[0]
            값 = _복구_분해_1[1]
            if ((i % 4) == 0):
                self.표오른쪽(1)
                if (i == 0):
                    self.가운데정렬()
                else:
                    self.표오른쪽(1)
                self.문장(값)
                continue
            if ((i % 4) == 1):
                self.표오른쪽(1)
                self.문장(((' ' + 값) + ' '))
                continue
            if ((i % 4) == 2):
                self.문장((값 + ' (☎ '))
                continue
            if not (((i % 4) == 3)):
                continue
            self.문장((값 + ')'))
        self.표처음()
        self.셀선택()
        self.표아래쪽((len(내용) - 1))
        self.셀병합()
        self.표나가기2()

